"""The journal file: a whole book as one readable text file."""

import re
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import account_type, valid_path
from tallybook.currency import CurrencyError, is_currency, parse_rate_text
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ParseError, TallybookError
from tallybook.ledger import Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money, parse_amount

__all__ = ["Journal", "JournalError", "parse_journal", "format_journal", "format_transaction"]

_TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_BLANKS = " \t"


class JournalError(ParseError):
    """A mistake in the writing of a journal file; `.line` is its 1-based line number."""

    def __init__(self, line, description="", **detail):
        if isinstance(line, str) and not description:
            # JournalError("line 3: ...") form, for completeness
            m = re.match(r"line ([0-9]+): ", line)
            message, line = line, (int(m.group(1)) if m else None)
        else:
            message = "line %d: %s" % (line, description)
        super().__init__(message, **detail)
        self.line = line


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: list = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def __post_init__(self):
        self.accounts = list(self.accounts)
        self.rates = list(self.rates)
        self.transactions = list(self.transactions)

    def to_ledger(self):
        ledger = Ledger()
        for acc in self.accounts:
            ledger.chart.add(acc.path, type=acc.type, currency=acc.currency, opened=acc.opened, note=acc.note)
            if acc.closed is not None:
                ledger.chart.close(acc.path, acc.closed)
        for src, dst, on, rate_text in self.rates:
            ledger.rates.set(src, dst, rate_text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


# ---------------------------------------------------------------------- reading


class _Mistake(Exception):
    pass


def _tokenize(line):
    """Split a line into ("bare"|"quoted", text) items and the comment text after `;` (or None)."""
    items = []
    comment = None
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in _BLANKS:
            i += 1
            continue
        if c == ";":
            comment = line[i + 1:]
            break
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise _Mistake("missing closing quote")
                ch = line[j]
                if ch == "\\":
                    if j + 1 < n and line[j + 1] in '"\\':
                        buf.append(line[j + 1])
                        j += 2
                        continue
                    raise _Mistake("invalid backslash in quoted text")
                if ch == '"':
                    break
                buf.append(ch)
                j += 1
            j += 1
            if j < n and line[j] not in _BLANKS and line[j] != ";":
                raise _Mistake("unexpected text after closing quote")
            items.append(("quoted", "".join(buf)))
            i = j
            continue
        j = i
        while j < n and line[j] not in _BLANKS and line[j] != ";":
            j += 1
        items.append(("bare", line[i:j]))
        i = j
    return items, comment


def _date(text):
    try:
        return parse_date(text)
    except DateError:
        raise _Mistake("invalid date '%s'" % text) from None


def _bare(item, what):
    kind, text = item
    if kind != "bare":
        raise _Mistake("unexpected quoted text, expected %s" % what)
    return text


def _parse_account(items):
    # items[0] is "account"
    if len(items) < 2:
        raise _Mistake("missing account path")
    path = _bare(items[1], "an account path")
    if not valid_path(path):
        raise _Mistake("invalid account path '%s'" % path)
    rest = items[2:]
    cur = opened = closed = None
    note = ""
    k = 0
    if k < len(rest) and rest[k][0] == "bare" and rest[k][1] not in ("open", "close"):
        cur = rest[k][1]
        if not is_currency(cur):
            raise _Mistake("unknown currency '%s'" % cur)
        k += 1
    for word in ("open", "close"):
        if k < len(rest) and rest[k] == ("bare", word):
            if k + 1 >= len(rest):
                raise _Mistake("missing date after %s" % word)
            d = _date(_bare(rest[k + 1], "a date"))
            if word == "open":
                opened = d
            else:
                closed = d
            k += 2
    if k < len(rest) and rest[k][0] == "quoted":
        note = rest[k][1]
        k += 1
    if k < len(rest):
        raise _Mistake("unexpected '%s'" % rest[k][1])
    if opened is not None and closed is not None and closed < opened:
        raise _Mistake("account %s is closed before it is opened" % path)
    return Account(path, account_type(path), cur, opened, closed, note)


def _parse_rate(items):
    words = [_bare(it, "a rate part") for it in items[1:]]
    if len(words) != 4:
        raise _Mistake("expected 'rate DATE FROM TO RATE'")
    d = _date(words[0])
    src, dst, text = words[1], words[2], words[3]
    for code in (src, dst):
        if not is_currency(code):
            raise _Mistake("unknown currency '%s'" % code)
    if src == dst:
        raise _Mistake("a rate needs two different currencies")
    try:
        parse_rate_text(text)
    except CurrencyError:
        raise _Mistake("invalid rate '%s'" % text) from None
    return (src, dst, d, text)


def _parse_tx_line(items):
    d = _date(items[0][1])
    k = 1
    flag = "*"
    if k < len(items) and items[k][0] == "bare" and items[k][1] in ("*", "!"):
        flag = items[k][1]
        k += 1
    strings = []
    while k < len(items) and items[k][0] == "quoted":
        strings.append(items[k][1])
        k += 1
    if not strings:
        raise _Mistake("missing payee")
    if len(strings) > 2:
        raise _Mistake("too many quoted strings")
    tags = set()
    while k < len(items):
        kind, text = items[k]
        if kind != "bare" or not text.startswith("#") or not _TAG_RE.fullmatch(text[1:]):
            raise _Mistake("unexpected '%s'" % text)
        tags.add(text[1:])
        k += 1
    payee = strings[0]
    narration = strings[1] if len(strings) > 1 else ""
    return Transaction(d, payee, narration, [], tuple(sorted(tags)), flag, None)


def _parse_posting(items, comment):
    words = [_bare(it, "a posting part") for it in items]
    note = comment.strip(" \t") if comment is not None else ""
    if not words:
        raise _Mistake("missing account")
    path = words[0]
    if not valid_path(path):
        raise _Mistake("invalid account path '%s'" % path)
    if len(words) == 1:
        return Posting(path, None, note)
    if len(words) == 2:
        raise _Mistake("missing currency after amount")
    if len(words) > 3:
        raise _Mistake("unexpected '%s'" % words[3])
    amount, code = words[1], words[2]
    if not is_currency(code):
        raise _Mistake("unknown currency '%s'" % code)
    try:
        minor = parse_amount(amount, code)
    except TallybookError as e:
        raise _Mistake(e.message) from None
    return Posting(path, Money(minor, code), note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError(1, "expected text, got %r" % (text,))
    if text.startswith("\ufeff"):
        text = text[1:]
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    journal = Journal()
    declared = set()
    current = None  # the Transaction whose postings are being read
    for number, line in enumerate(lines, 1):
        if line.endswith("\r"):
            line = line[:-1]
        try:
            stripped = line.lstrip(_BLANKS)
            if not stripped:
                current = None
                continue
            if stripped[0] in ";#":
                continue
            items, comment = _tokenize(line)
            if line[0] in _BLANKS:
                if current is None:
                    raise _Mistake("indented line outside a transaction")
                current.postings.append(_parse_posting(items, comment))
                continue
            current = None
            head = items[0] if items else ("bare", "")
            if head == ("bare", "account"):
                acc = _parse_account(items)
                if acc.path in declared:
                    raise _Mistake("account %s is declared twice" % acc.path)
                declared.add(acc.path)
                journal.accounts.append(acc)
            elif head == ("bare", "rate"):
                journal.rates.append(_parse_rate(items))
            elif head[0] == "bare" and head[1][:1].isdigit():
                current = _parse_tx_line(items)
                journal.transactions.append(current)
            else:
                raise _Mistake("unexpected '%s'" % head[1])
        except _Mistake as e:
            raise JournalError(number, str(e)) from None
    return journal


# ---------------------------------------------------------------------- writing


def _quote(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _account_line(acc):
    parts = ["account", acc.path]
    if acc.currency is not None:
        parts.append(acc.currency)
    if acc.opened is not None:
        parts += ["open", format_date(acc.opened)]
    if acc.closed is not None:
        parts += ["close", format_date(acc.closed)]
    if acc.note:
        parts.append(_quote(acc.note))
    return " ".join(parts)


def _rate_line(rate):
    src, dst, on, text = rate
    return "rate %s %s %s %s" % (format_date(on), src, dst, text)


def format_transaction(tx):
    head = "%s %s %s" % (format_date(tx.date), tx.flag, _quote(tx.payee))
    if tx.narration:
        head += " " + _quote(tx.narration)
    for tag in sorted(set(tx.tags)):
        head += " #" + tag
    lines = [head]
    with_amount = [p for p in tx.postings if p.amount is not None]
    acc_width = max((len(p.account) for p in with_amount), default=0)
    amt_width = max((len(p.amount.amount_str()) for p in with_amount), default=0)
    for p in tx.postings:
        if p.amount is None:
            line = "  " + p.account
        else:
            line = "  %s  %s %s" % (p.account.ljust(acc_width), p.amount.amount_str().rjust(amt_width),
                                    p.amount.currency)
        if p.note:
            line += "  ; " + p.note
        lines.append(line)
    return "\n".join(lines) + "\n"


def format_journal(journal):
    groups = []
    if journal.accounts:
        groups.append("".join(_account_line(a) + "\n" for a in journal.accounts))
    if journal.rates:
        groups.append("".join(_rate_line(r) + "\n" for r in journal.rates))
    if journal.transactions:
        groups.append("\n".join(format_transaction(t) for t in journal.transactions))
    return "\n".join(groups)

"""The query language for finding transactions."""

import operator
import re
from fractions import Fraction

from tallybook.currency import is_currency
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError

__all__ = ["parse_query", "select", "Query", "QueryError"]


class QueryError(ParseError):
    """A query that cannot be understood; `.position` is the 1-based place of the mistake."""

    def __init__(self, description, position, **detail):
        super().__init__("%s at position %d" % (description, position), **detail)
        self.position = position


_SPACES = " \t"
_STOP = " \t()"
_NAME_RE = re.compile(r"[A-Za-z][A-Za-z0-9_-]*")
_OP_RE = re.compile(r"<=|>=|!=|<|>|=")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+")
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_NAMES = ("payee", "narration", "tag", "date", "flag", "id", "account")
_COMPARABLE = ("date", "amount")
_KEYWORDS = ("and", "or", "not")
_OPS = {
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
    "=": operator.eq,
    "!=": operator.ne,
}


# ------------------------------------------------------------------ the tree


class _Node:
    on_posting = False

    def eval(self, tx, posting):  # pragma: no cover - overridden
        raise NotImplementedError


class _And(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, posting):
        return self.left.eval(tx, posting) and self.right.eval(tx, posting)


class _Or(_Node):
    def __init__(self, left, right):
        self.left, self.right = left, right

    def eval(self, tx, posting):
        return self.left.eval(tx, posting) or self.right.eval(tx, posting)


class _Not(_Node):
    def __init__(self, inner):
        self.inner = inner

    def eval(self, tx, posting):
        return not self.inner.eval(tx, posting)


class _Contains(_Node):
    def __init__(self, fields, text):
        self.fields = fields
        self.text = text.lower()

    def eval(self, tx, posting):
        for f in self.fields:
            value = getattr(tx, f, None)
            if isinstance(value, str) and self.text in value.lower():
                return True
        return False


class _Tag(_Node):
    def __init__(self, name):
        self.name = name.lower()

    def eval(self, tx, posting):
        return any(isinstance(t, str) and t.lower() == self.name for t in (tx.tags or ()))


class _InPeriod(_Node):
    def __init__(self, period):
        self.period = period

    def eval(self, tx, posting):
        return self.period.start <= tx.date <= self.period.end


class _DateCmp(_Node):
    def __init__(self, op, date):
        self.op, self.date = _OPS[op], date

    def eval(self, tx, posting):
        return self.op(tx.date, self.date)


class _Flag(_Node):
    def __init__(self, flag):
        self.flag = flag

    def eval(self, tx, posting):
        return tx.flag == self.flag


class _Id(_Node):
    def __init__(self, value):
        self.value = value

    def eval(self, tx, posting):
        return tx.id is not None and not isinstance(tx.id, bool) and tx.id == self.value


class _Account(_Node):
    def __init__(self, parts):
        self.parts = parts

    def eval(self, tx, posting):
        return isinstance(posting.account, str) and _pattern_matches(self.parts, posting.account)


class _AmountCmp(_Node):
    def __init__(self, op, value, code):
        self.op, self.value, self.code = _OPS[op], value, code

    def eval(self, tx, posting):
        m = posting.amount
        if m is None:
            return False
        if self.code is not None and m.currency != self.code:
            return False
        return self.op(Fraction(m.minor, 10 ** m.exponent), self.value)


def _pattern_matches(parts, path):
    """Does the pattern name the account (or an account above it)?"""
    segs = path.split(":")

    def match(i, j):
        if i == len(parts):
            return True  # the account may go on below
        p = parts[i]
        if p == "**":
            return any(match(i + 1, k) for k in range(j, len(segs) + 1))
        if j >= len(segs):
            return False
        if p == "*" or p == segs[j]:
            return match(i + 1, j + 1)
        return False

    return match(0, 0)


def _compile_pattern(text):
    parts = text.split(":")
    for p in parts:
        if p in ("*", "**"):
            continue
        if not _PART_RE.fullmatch(p):
            return None
    return parts


# ----------------------------------------------------------------- the lexer


class _Token:
    __slots__ = ("kind", "pos", "node", "error")

    def __init__(self, kind, pos, node=None, error=None):
        self.kind = kind  # "term", "and", "or", "not", "(", ")", "end", "error"
        self.pos = pos
        self.node = node
        self.error = error


def _read_quoted(text, i):
    """Read a quoted string whose opening quote is at index i; return (value, index after it)."""
    n = len(text)
    j = i + 1
    buf = []
    while True:
        if j >= n:
            raise QueryError("unterminated quote", i + 1)
        c = text[j]
        if c == "\\" and j + 1 < n and text[j + 1] in '"\\':
            buf.append(text[j + 1])
            j += 2
            continue
        if c == '"':
            break
        buf.append(c)
        j += 1
    j += 1
    if j < n and text[j] not in _STOP:
        raise QueryError("unexpected text after closing quote", j + 1)
    return "".join(buf), j


def _read_bare(text, i):
    j = i
    while j < len(text) and text[j] not in _STOP:
        j += 1
    return text[i:j], j


def _make_term(name, value, quoted, start, chart, op=None):
    """Build the node for one term; `start` is the 1-based position of the term."""
    def bad(what):
        return QueryError("%s in '%s'" % (what, term_text), start)

    term_text = "%s%s%s" % (name, op or ":", value)
    if value == "":
        if quoted:
            raise bad("empty quotes")
        raise bad("missing value")
    if op is None:
        if name in ("payee", "narration"):
            return _Contains((name,), value)
        if name == "tag":
            return _Tag(value)
        if name == "date":
            try:
                return _InPeriod(Period.parse(value))
            except DateError:
                raise bad("invalid period") from None
        if name == "flag":
            if value not in ("*", "!"):
                raise bad("invalid flag, expected * or !")
            return _Flag(value)
        if name == "id":
            if not re.fullmatch(r"[0-9]+", value):
                raise bad("invalid id, expected digits")
            return _Id(int(value))
        if name == "account":
            parts = _compile_pattern(value)
            if parts is None:
                raise bad("invalid account pattern")
            if chart is not None and not any(_pattern_matches(parts, a.path) for a in chart.accounts()):
                raise QueryError("no account matches '%s'" % term_text, start)
            return _Account(parts)
        raise AssertionError(name)  # pragma: no cover
    if name == "date":
        try:
            return _DateCmp(op, parse_date(value))
        except DateError:
            raise bad("invalid date") from None
    # amount
    m = _AMOUNT_RE.fullmatch(value) if not quoted else None
    if m is None:
        raise bad("invalid amount")
    number, code = m.groups()
    if code:
        if not re.fullmatch(r"[A-Z]{3}", code) or not is_currency(code):
            raise bad("invalid currency")
    return _AmountCmp(op, Fraction(number), code or None)


def _lex(text, chart):
    """The tokens of the query; a mistake becomes an "error" token where it stands."""
    tokens = []
    i, n = 0, len(text)
    try:
        while i < n:
            c = text[i]
            if c in _SPACES:
                i += 1
                continue
            start = i + 1
            if c in "()":
                tokens.append(_Token(c, start))
                i += 1
                continue
            if c == '"':
                value, i = _read_quoted(text, i)
                if value == "":
                    raise QueryError("empty quotes", start)
                tokens.append(_Token("term", start, _Contains(("payee", "narration"), value)))
                continue
            m = _NAME_RE.match(text, i)
            if m:
                name = m.group(0).lower()
                j = m.end()
                if j < n and text[j] == ":":
                    if name not in _NAMES:
                        raise QueryError("unknown name '%s'" % m.group(0), start)
                    j += 1
                    if j < n and text[j] == '"':
                        value, i = _read_quoted(text, j)
                        quoted = True
                    else:
                        value, i = _read_bare(text, j)
                        quoted = False
                    tokens.append(_Token("term", start, _make_term(name, value, quoted, start, chart)))
                    continue
                if name in _COMPARABLE:
                    k = j
                    while k < n and text[k] in _SPACES:
                        k += 1
                    om = _OP_RE.match(text, k)
                    if om:
                        k = om.end()
                        while k < n and text[k] in _SPACES:
                            k += 1
                        value, i = _read_bare(text, k)
                        tokens.append(_Token("term", start,
                                             _make_term(name, value, False, start, chart, om.group(0))))
                        continue
            word, i = _read_bare(text, i)
            if word.lower() in _KEYWORDS:
                tokens.append(_Token(word.lower(), start))
            else:
                tokens.append(_Token("term", start, _Contains(("payee", "narration"), word)))
    except QueryError as e:
        tokens.append(_Token("error", e.position, error=e))
        return tokens
    tokens.append(_Token("end", n + 1))
    return tokens


# ---------------------------------------------------------------- the parser


class _Parser:
    def __init__(self, tokens):
